#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }

    long long *col_sum = (long long *)calloc(m, sizeof(long long));
    if (!col_sum) return 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            long long val;
            scanf("%lld", &val);
            col_sum[j] += val;
        }
    }

    long long min_cost = col_sum[0];
    for (int j = 1; j < m; j++) {
        if (col_sum[j] < min_cost) {
            min_cost = col_sum[j];
        }
    }

    printf("%lld\n", min_cost);

    free(col_sum);
    return 0;
}
```

